#include <stdio.h>
#include <stdlib.h>

struct Point {
    int x;
    int y;
};

int main() {
    struct Point p = {10, 20};
    struct Point *ptr = &p;

    // 점(.) 연산자
    printf("p.x = %d\n", p.x);

    // 역참조 후 점
    printf("(*ptr).x = %d\n", (*ptr).x);

    // 화살표 연산자 (더 편리!)
    printf("ptr->x = %d\n", ptr->x);

    // 값 변경
    ptr->y = 100;
    printf("p.y = %d\n", p.y);

    return 0;
}
